{
  "story": "Cells divide to grow and repair. Follow chromosomes through the five stages of mitosis to see how DNA splits evenly into two new nuclei.",
  "aha": {
    "stateId": "anaphase",
    "observation": "Sister chromatids pull apart toward opposite poles, ensuring each new cell gets an identical set of chromosomes."
  },
  "layout": {
    "preset": "standard",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.stepIndex",
        "items": "variant.states"
      }
    },
    {
      "id": "pic",
      "kind": "fixed-picture",
      "bind": {
        "active": "state.active",
        "regions": "variant.regions"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "reason": "state.why",
        "target": "state.calloutRegion",
        "text": "state.sentence"
      }
    },
    {
      "id": "readouts",
      "kind": "value-readout",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "stepIndex",
      "kind": "index",
      "label": "Mitosis Phase",
      "options": [
        "Prophase",
        "Prometaphase",
        "Metaphase",
        "Anaphase",
        "Telophase"
      ]
    },
    {
      "id": "resetBtn",
      "kind": "reset",
      "label": "Reset",
      "options": []
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Mitosis Cycle",
        "regions": [
          {
            "id": "chromosomes",
            "label": "Chromosomes",
            "kind": "dna",
            "values": ["Condensed", "Aligned", "Separating", "Decondensing"]
          },
          {
            "id": "spindle",
            "label": "Spindle Fibers",
            "kind": "protein",
            "values": ["Forming", "Attached", "Pulling", "Disassembling"]
          },
          {
            "id": "nucleus",
            "label": "Nuclear Membrane",
            "kind": "barrier",
            "values": ["Intact", "Broken Down", "Reforming"]
          }
        ],
        "states": [
          {
            "id": "prophase",
            "label": "Prophase",
            "short": "Condense",
            "sentence": "Chromatin condenses into visible chromosomes while spindle fibers start to form outside the nucleus.",
            "why": "DNA must compact tightly so it can move safely without tangling.",
            "active": ["chromosomes", "spindle"],
            "calloutRegion": "chromosomes",
            "readouts": [
              {
                "id": "r1",
                "label": "Condensation",
                "value": "High"
              },
              {
                "id": "r2",
                "label": "Membrane",
                "value": "Intact"
              }
            ]
          },
          {
            "id": "prometaphase",
            "label": "Prometaphase",
            "short": "Attach",
            "sentence": "The nuclear envelope breaks down completely, allowing spindle fibers to attach to chromosome kinetochores.",
            "why": "Fibers need direct physical access to move the chromosomes.",
            "active": ["chromosomes", "spindle", "nucleus"],
            "calloutRegion": "nucleus",
            "readouts": [
              {
                "id": "r1",
                "label": "Condensation",
                "value": "High"
              },
              {
                "id": "r2",
                "label": "Membrane",
                "value": "Dissolved"
              }
            ]
          },
          {
            "id": "metaphase",
            "label": "Metaphase",
            "short": "Align",
            "sentence": "Chromosomes align neatly along the center of the cell at the metaphase plate.",
            "why": "Central alignment ensures equal distribution before pulling begins.",
            "active": ["chromosomes", "spindle"],
            "calloutRegion": "chromosomes",
            "readouts": [
              {
                "id": "r1",
                "label": "Alignment",
                "value": "Center"
              },
              {
                "id": "r2",
                "label": "Tension",
                "value": "Balanced"
              }
            ]
          },
          {
            "id": "anaphase",
            "label": "Anaphase",
            "short": "Pull Apart",
            "sentence": "Sister chromatids separate and are pulled toward opposite poles by shortening spindle fibers.",
            "why": "This is the core separation step creating two identical sets of DNA.",
            "active": ["chromosomes", "spindle"],
            "calloutRegion": "chromosomes",
            "readouts": [
              {
                "id": "r1",
                "label": "Separation",
                "value": "Active"
              },
              {
                "id": "r2",
                "label": "Poles",
                "value": "Moving"
              }
            ]
          },
          {
            "id": "telophase",
            "label": "Telophase",
            "short": "Reform",
            "sentence": "Two new nuclear envelopes reform around the separated sets of chromosomes as they decondense.",
            "why": "The cell restores its resting compartments before final division.",
            "active": ["chromosomes", "nucleus"],
            "calloutRegion": "nucleus",
            "readouts": [
              {
                "id": "r1",
                "label": "Nuclei",
                "value": "Two"
              },
              {
                "id": "r2",
                "label": "Membrane",
                "value": "Reformed"
              }
            ]
          }
        ]
      }
    ]
  }
}
